// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(c));
        bound(amount, 0, 2**100);
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertTrue(address(c).balance == before - amount);
    }
}
